type RunStatus = 'queued' | 'running' | 'completed' | 'failed' | 'cancelled';

type TrainingRun = {
  id: string;
  status: RunStatus;
  progress: number | null;
  lifecycleSequence: number;
  startedAt: string | null;
  terminalAt: string | null;
};

type MetricPoint = {
  eventId: string;
  sequence: number;
  metric: string;
  unit: string;
  step: number;
  timestamp: string;
  value: number;
};

type LogEvent = {
  eventId: string;
  sequence: number;
  timestamp: string;
  level: 'info' | 'warn' | 'error';
  message: string;
};

type RunEvent =
  | { eventId: string; sequence: number; cursor: string; type: 'run.updated'; run: TrainingRun }
  | { eventId: string; sequence: number; cursor: string; type: 'metric.recorded'; point: MetricPoint }
  | { eventId: string; sequence: number; cursor: string; type: 'log.appended'; log: LogEvent };

type RunSnapshot = {
  schemaVersion: 1;
  run: TrainingRun;
  metrics: Record<string, MetricPoint[]>;
  logs: LogEvent[];
  contiguousSequence: number;
  resumeCursor: string;
};

type MonitorState = {
  contiguousSequence: number;
  resumeCursor: string | null;
  freshness: 'fresh' | 'reconnecting' | 'stale';
  gapAfterSequence: number | null;
  receivedEventIds: Set<string>;
};
